require __DIR__.'/auth.php';requireAdmin();require dirname(__DIR__).'/includes/bootstrap.php';require dirname(__DIR__).'/includes/listings.php';require_once dirname(__DIR__).'/Config/blog-store.php';
$db=adminDb();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 adminCsrf();$id=filter_var($_POST['id']??0,FILTER_VALIDATE_INT);$action=is_string($_POST['action']??null)?$_POST['action']:'';
 if(!$id||!in_array($action,['approve','reject','pending','delete'],true))$errors[]='Choose a valid comment and action.';
 if(!$errors){try{
  $q=$db->prepare('SELECT id FROM blog_comments WHERE id=?');$q->execute([$id]);if(!$q->fetchColumn())$errors[]='This comment no longer exists.';
  else{if($action==='delete')$db->prepare('DELETE FROM blog_comments WHERE id=?')->execute([$id]);else{$status=['approve'=>'approved','reject'=>'rejected','pending'=>'pending'][$action];$db->prepare('UPDATE blog_comments SET status=?,updated_at=NOW() WHERE id=?')->execute([$status,$id]);}$_SESSION['blog_comment_notice']=$action==='delete'?'Comment deleted.':'Comment status updated.';header('Location: ./blog-comments?'.http_build_query(['status'=>is_string($_GET['status']??null)?$_GET['status']:'pending','post'=>max(0,(int)($_GET['post']??0)),'q'=>is_string($_GET['q']??null)?$_GET['q']:'','page'=>max(1,(int)($_GET['page']??1))]));exit;}
 }catch(Throwable $exception){$errors[]='Could not update this comment. Please try again.';}}
}
$status=is_string($_GET['status']??null)?$_GET['status']:'pending';if(!in_array($status,['','pending','approved','rejected'],true))$status='pending';$post=max(0,(int)($_GET['post']??0));$query=is_string($_GET['q']??null)?mb_substr(trim($_GET['q']),0,150):'';$where=[];$params=[];
if($status!==''){$where[]='c.status=?';$params[]=$status;}if($post){$where[]='c.post_id=?';$params[]=$post;}if($query!==''){$where[]='(c.name LIKE ? OR c.email LIKE ? OR c.body LIKE ? OR p.payload LIKE ?)';for($i=0;$i<4;$i++)$params[]='%'.$query.'%';}
$condition=$where?' WHERE '.implode(' AND ',$where):'';$q=$db->prepare('SELECT COUNT(*) FROM blog_comments c INNER JOIN blog_posts p ON p.id=c.post_id'.$condition);$q->execute($params);$total=(int)$q->fetchColumn();$pages=max(1,(int)ceil($total/6));$page=max(1,min($pages,(int)($_GET['page']??1)));$offset=($page-1)*6;
$q=$db->prepare('SELECT c.*,p.slug,p.payload FROM blog_comments c INNER JOIN blog_posts p ON p.id=c.post_id'.$condition.' ORDER BY c.created_at DESC,c.id DESC LIMIT 6 OFFSET '.$offset);$q->execute($params);$comments=$q->fetchAll();$postOptions=[];foreach($db->query('SELECT id,slug,payload FROM blog_posts ORDER BY id DESC') as $row)$postOptions[]=blogRecord($row);
function blogCommentUrl(array $changes=[]): string {global $status,$post,$query,$page;return './blog-comments?'.http_build_query(array_merge(['status'=>$status,'post'=>$post,'q'=>$query,'page'=>$page],$changes));}
$notice=$_SESSION['blog_comment_notice']??'';unset($_SESSION['blog_comment_notice']);$properties=listingData();$view='blog';$title='Blog comments';require __DIR__.'/header.php';
