<link rel="stylesheet" href="./blog.css?v=<?= filemtime(__DIR__.'/blog.css') ?>"><script src="./blog.js?v=<?= filemtime(__DIR__.'/blog.js') ?>" defer></script>
<div class="page-heading"><div><span class="eyebrow">COMMUNITY</span><h1>Blog comments</h1><p>Review comments before they appear on your website. Only approved comments are public.</p></div><a class="role-button" href="./blog">Back to posts</a></div>
<?php if($notice): ?><div class="success-note" role="status"><?= e($notice) ?></div><?php endif; ?><?php if($errors): ?><div class="form-error" role="alert"><?= e(implode(' ',$errors)) ?></div><?php endif; ?>
<section class="panel form-section"><form class="blog-search" method="get"><input name="q" value="<?= e($query) ?>" placeholder="Search comments, authors or posts" aria-label="Search comments"><select name="status" aria-label="Comment status"><?php foreach([''=>'All statuses','pending'=>'Pending','approved'=>'Approved','rejected'=>'Rejected'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $status===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><select name="post" aria-label="Filter blog post"><option value="0">All posts</option><?php foreach($postOptions as $option): ?><option value="<?= $option['id'] ?>" <?= $post===$option['id']?'selected':'' ?>><?= e($option['title']) ?></option><?php endforeach; ?></select><button class="primary-button" type="submit">Search</button><a href="./blog-comments?status=">Reset</a></form><p><?= $total ?> comment<?= $total===1?'':'s' ?><?= $total?' &middot; Showing '.($offset+1).'&ndash;'.min($offset+6,$total):'' ?></p></section>
<div class="blog-comment-grid"><?php foreach($comments as $comment): $payload=json_decode($comment['payload'],true)?:[]; ?><article class="panel blog-comment-card"><div class="blog-comment-top"><div><h2><?= e($comment['name']) ?></h2><div class="blog-comment-meta"><?= e($comment['email']) ?><br><?= e($comment['created_at']) ?> &middot; Pakistan time</div></div><span class="blog-comment-tag is-<?= e($comment['status']) ?>"><?= e(ucfirst($comment['status'])) ?></span></div><p class="blog-comment-meta">On <a href="../blog?article=<?= rawurlencode($comment['slug']) ?>" target="_blank" rel="noopener"><?= e($payload['title']??$comment['slug']) ?></a></p><p class="blog-comment-body"><?= e($comment['body']) ?></p><div class="blog-card-actions"><?php foreach(['approve'=>'Approve','reject'=>'Reject','pending'=>'Return to pending'] as $action=>$label): if($comment['status']===['approve'=>'approved','reject'=>'rejected','pending'=>'pending'][$action])continue; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(adminToken()) ?>"><input type="hidden" name="id" value="<?= (int)$comment['id'] ?>"><button class="<?= $action==='approve'?'primary-button':'role-button' ?>" type="submit" name="action" value="<?= $action ?>"><?= e($label) ?></button></form><?php endforeach; ?><form method="post" class="delete-user-form blog-comment-delete-form" data-title="<?= e('Comment by '.$comment['name']) ?>"><input type="hidden" name="csrf" value="<?= e(adminToken()) ?>"><input type="hidden" name="id" value="<?= (int)$comment['id'] ?>"><input type="hidden" name="action" value="delete"><button class="role-button" type="submit">Delete</button></form></div></article><?php endforeach; ?></div>
<?php if(!$comments): ?><section class="panel empty-state"><h2>No comments to review</h2><p>New comments will appear here. Change the filters to see earlier comments.</p></section><?php endif; ?>
<?php if($pages>1): ?><nav class="blog-pagination" aria-label="Comment pagination"><?php if($page>1): ?><a href="<?= e(blogCommentUrl(['page'=>$page-1])) ?>">&larr; Previous</a><?php endif; ?><?php for($n=1;$n<=$pages;$n++): if($n===1||$n===$pages||abs($n-$page)<=1): ?><a href="<?= e(blogCommentUrl(['page'=>$n])) ?>" <?= $n===$page?'aria-current="page"':'' ?>><?= $n ?></a><?php elseif(abs($n-$page)===2): ?><span>&hellip;</span><?php endif; endfor; ?><?php if($page<$pages): ?><a href="<?= e(blogCommentUrl(['page'=>$page+1])) ?>">Next &rarr;</a><?php endif; ?></nav><?php endif; ?>
